def check_local_constraint(a, b):
    neighbors = [
        (1, 0), (1, 1), (0, 1), (-1, 0), (-1, 1), (0, -1), (1, -1), (-1, -1)
    ]
    for dx, dy in neighbors:
        # Check if a*dx + b*dy == 0 mod 4
        if (a * dx + b * dy) % 4 == 0:
            return False, (dx, dy)
    return True, None

a, b = 1, 2
is_valid, failing_neighbor = check_local_constraint(a, b)
print(f"Local constraint check for (a={a}, b={b}): Valid={is_valid}")
if not is_valid:
    print(f"Failing neighbor: {failing_neighbor}")

